const e="JPEG",n="Основний",i="Органи",r="Плече",s="Обертальна манжета",t="Синовіальна сумка (бурса)",a="Лопатка",l="Scapula",u="Clavicula",d="Плечова кістка",c="Humerus",h="Дельтоподібний м’яз",m="Триголовий м’яз плеча (тріцепс)",o="Трапецієподібний м’яз",b="Суглобова капсула",g="Суглобова губа (лабрум)",k="Акроміально-ключичний суглоб",f="Міжхребцеві диски",p="Нерви",z="М’язи",S="Поперекові хребці",w="Тазові кістки",v="Драглисте ядро",B="Сідничний нерв",K="Грудні хребці",E="Ребра",H="Costae",D="Реберні хрящі",M="Груднина",A="Sternum",R="Ромбоподібні м’язи",G="Міжреберні м’язи",O="Atlas",L="Axis",W="Каркова зв’язка",N="Хребетна артерія",V="Груднинно-ключично-соскоподібний м’яз",F="Драбинчасті м’язи",U="Розгиначі шиї",Z="М’яз, що піднімає лопатку",I="Щелепний суглоб",T="Жувальні м’язи",P="Лобова кістка",x="Тім’яні кістки",j="Потилична кістка",y="Клиноподібна кістка",C="Виличні кістки",J="Верхня щелепа",_="Maxilla",q="Нижня щелепа",Q="Mandibula",X="Dentes",Y="Суглобовий диск",$="Жувальний м’яз",ee="Лікоть",ne="Ліктьова кістка",ie="Ulna",re="Променева кістка",se="Radius",te="Біцепс",ae="Плечовий м’яз",le="Плечепроменевий м’яз",ue="Кільцева зв’язка",de="Внутрішня бокова зв’язка",ce="Ліктьовий нерв",he="Кисть",me="Сухожилкові піхви",oe="Човноподібна кістка",be="Сідлоподібний суглоб великого пальця",ge="Кістки зап’ястка",ke="П’ясткові кістки",fe="Кістки пальців",pe="Phalanges",ze="Сухожилки великого пальця",Se="Підвищення великого пальця",we="Thenar",ve="Підвищення мізинця",Be="Hypothenar",Ke="Утримувач сухожилків згиначів (карпальна зв’язка)",Ee="Серединний нерв",He={"(prefers-reduced-motion: reduce)":"(prefers-reduced-motion: reduce)","ruhebild__welle ruhebild__welle--kupfer":"ruhebild__welle ruhebild__welle--kupfer","header, h2, h3, h4, p, li, section, article, footer, figure":"header, h2, h3, h4, p, li, section, article, footer, figure",JPEG:e,"Fehler in einem Modul:":"Помилка в модулі:","Querverweise ohne Ziel (kern/verweise.ts):":"Перехресні посилання без цілі (kern/verweise.ts):",Haupt:n,"Modell wird geladen …":"Модель завантажується …","Das 3D-Modell lässt sich hier nicht anzeigen. Bitte die Seite neu laden.":"3D-модель тут не відображається. Будь ласка, перезавантажте сторінку.","Von vorn":"Спереду","Von der Seite":"Збоку","Von hinten":"Ззаду","Von innen":"Зсередини","Schräg von rechts":"Навскіс справа","Schräg von links":"Навскіс зліва","Von oben":"Зверху","Von unten":"Знизу","Gelenke und Knochen":"Суглоби та кістки",Organe:i,Schulter:r,"Die Schulter":"Плече","Das beweglichste Gelenk des Körpers. Die Pfanne ist klein und flach – Halt geben vor allem Muskeln und Sehnen.":"Найрухоміший суглоб тіла. Суглобова западина маленька й пласка – суглоб тримають переважно м’язи та сухожилки.",Rotatorenmanschette:s,"Weitere Muskeln":"Інші м’язи","Gelenk und Bänder":"Суглоб і зв’язки",Schleimbeutel:t,Schulterblatt:a,Scapula:l,"Flacher, dreieckiger Knochen hinten am Brustkorb. Außen trägt er die Gelenkpfanne, oben das Schulterdach.":"Пласка трикутна кістка на задній стороні грудної клітки. Із зовнішнього боку на ній розташована суглобова западина, зверху – акроміон (дах плеча).","Er gleitet bei jeder Armbewegung auf dem Brustkorb mit und ist Ansatz für viele Muskeln.":"Вона ковзає по грудній клітці під час кожного руху руки й слугує місцем прикріплення багатьох м’язів.","Schmerzen am Schulterblatt kommen meist von verspannten Muskeln, selten vom Knochen selbst.":"Біль у ділянці лопатки здебільшого спричинений напруженими м’язами, рідко – самою кісткою.",Schlüsselbein:"Ключиця",Clavicula:u,"Verläuft vorn vom Brustbein nach außen zum Schulterdach. Man kann es unter der Haut tasten.":"Іде спереду від груднини назовні до даху плеча. Її можна намацати під шкірою.","Es stützt die Schulter nach außen ab – die einzige knöcherne Verbindung zwischen Arm und Rumpf.":"Вона підтримує плече ззовні – єдиний кістковий зв’язок між рукою і тулубом.","Bricht bei Stürzen auf die Schulter oder den ausgestreckten Arm recht häufig.":"Досить часто ламається під час падіння на плече або на витягнуту руку.",Oberarmknochen:d,Humerus:c,"Sein kugeliger Kopf liegt in der flachen Pfanne des Schulterblatts.":"Її кругла голівка лежить у пласкій западині лопатки.","Kopf und Pfanne bilden das eigentliche Schultergelenk. An den Höckern neben dem Kopf setzen die Sehnen an.":"Голівка й западина утворюють власне плечовий суглоб. До горбків поруч із голівкою прикріплюються сухожилки.","Verschleiß am Gelenkknorpel (Arthrose) oder ein Bruch am Oberarmkopf nach einem Sturz.":"Зношення суглобового хряща (артроз) або перелом голівки плечової кістки після падіння.",Obergrätenmuskel:"Надостьовий м’яз","Musculus supraspinatus":"Musculus supraspinatus","Liegt oben auf dem Schulterblatt. Seine Sehne zieht unter dem Schulterdach hindurch zum Oberarmkopf.":"Лежить угорі на лопатці. Його сухожилок проходить під дахом плеча до голівки плечової кістки.","Er hebt den Arm zur Seite an und drückt den Oberarmkopf in die Pfanne.":"Він піднімає руку вбік і притискає голівку плечової кістки до западини.","Unter dem Schulterdach ist es eng. Die Sehne kann dort gereizt werden, einklemmen oder einreißen – typisch ist Schmerz beim seitlichen Anheben.":"Під дахом плеча тісно. Сухожилок там може подразнюватися, затискатися або надриватися – типовий біль під час піднімання руки вбік.","Untergräten­muskel":"Підостьовий м’яз","Musculus infraspinatus":"Musculus infraspinatus","Bedeckt die Rückseite des Schulterblatts unterhalb der Schulterblattgräte.":"Покриває задню поверхню лопатки нижче ості лопатки.","Er dreht den Arm nach außen, zum Beispiel beim Haarekämmen.":"Він повертає руку назовні, наприклад, коли Ви розчісуєте волосся.","Ist er geschädigt, fällt das Drehen des Arms nach außen schwer und schmerzt.":"Якщо він пошкоджений, повертати руку назовні важко й боляче.","Kleiner Rundmuskel":"Малий круглий м’яз","Musculus teres minor":"Musculus teres minor","Schmaler Muskel am äußeren Rand des Schulterblatts, direkt unter dem Untergrätenmuskel.":"Вузький м’яз на зовнішньому краї лопатки, безпосередньо під підостьовим м’язом.","Er hilft beim Drehen des Arms nach außen.":"Він допомагає повертати руку назовні.","Macht allein selten Beschwerden, ist bei großen Sehnenrissen aber mitbetroffen.":"Сам по собі рідко спричиняє скарги, але за великих розривів сухожилків теж уражається.","Unterschulter­blattmuskel":"Підлопатковий м’яз","Musculus subscapularis":"Musculus subscapularis","Liegt auf der Vorderseite des Schulterblatts, zwischen Schulterblatt und Rippen.":"Лежить на передній поверхні лопатки, між лопаткою та ребрами.","Er dreht den Arm nach innen – etwa wenn Sie die Hand auf den Rücken legen.":"Він повертає руку всередину – наприклад, коли Ви кладете руку за спину.","Bei einem Riss schmerzt die Schulter vorn, und die Hand lässt sich kaum hinter den Rücken führen.":"За розриву плече болить спереду, і руку майже неможливо завести за спину.",Deltamuskel:h,"Musculus deltoideus":"Musculus deltoideus","Liegt wie eine Kappe über der Schulter und gibt ihr die runde Form.":"Лежить над плечем, як шапочка, і надає йому округлої форми.","Der kräftigste Armheber: nach vorn, zur Seite und nach hinten.":"Найсильніший м’яз, що піднімає руку: уперед, убік і назад.","Schmerzen außen am Oberarm werden oft hier gespürt, kommen aber meist von den Sehnen darunter.":"Біль на зовнішньому боці плеча часто відчувається тут, але здебільшого походить від сухожилків під м’язом.","Lange Bizepssehne":"Довга головка сухожилка біцепса","Musculus biceps brachii, Caput longum":"Musculus biceps brachii, Caput longum","Die Sehne läuft in einer Rinne vorn am Oberarmkopf und zieht durch das Gelenk bis zum Pfannenrand.":"Сухожилок проходить у жолобку на передній стороні голівки плечової кістки й через суглоб сягає краю западини.","Der Bizeps beugt den Ellenbogen und dreht den Unterarm.":"Біцепс згинає лікоть і повертає передпліччя.","Die Sehne kann sich in ihrer Rinne entzünden – dann schmerzt die Schulter vorn. Reißt sie, rutscht der Muskelbauch nach unten.":"Сухожилок може запалитися у своєму жолобку – тоді плече болить спереду. Якщо він розривається, м’язове черевце зміщується вниз.","Kurzer Bizepskopf":"Коротка головка біцепса","Musculus biceps brachii, Caput breve":"Musculus biceps brachii, Caput breve","Entspringt am Rabenschnabelfortsatz, einem Knochenvorsprung vorn am Schulterblatt.":"Починається від дзьобоподібного відростка – кісткового виступу на передній стороні лопатки.","Beugt zusammen mit dem langen Kopf den Ellenbogen.":"Разом із довгою головкою згинає лікоть.","Macht selten Probleme.":"Рідко завдає проблем.",Trizeps:m,"Musculus triceps brachii":"Musculus triceps brachii","Liegt auf der Rückseite des Oberarms. Ein Teil entspringt unterhalb der Gelenkpfanne.":"Лежить на задній стороні плеча. Одна його частина починається нижче від суглобової западини.","Er streckt den Ellenbogen.":"Він розгинає лікоть.","An der Schulter selten beteiligt.":"У плечовому суглобі бере участь рідко.","Großer Rundmuskel":"Великий круглий м’яз","Musculus teres major":"Musculus teres major","Zieht von der unteren Spitze des Schulterblatts nach vorn zum Oberarm.":"Іде від нижнього кута лопатки вперед до плечової кістки.","Er zieht den Arm an den Körper heran und dreht ihn nach innen.":"Він наближає руку до тіла й повертає її всередину.","Kann bei Überlastung verspannen, etwa nach Klimmzügen oder Rudern.":"За перевантаження може напружуватися, наприклад, після підтягувань або веслування.","Großer Brustmuskel":"Великий грудний м’яз","Musculus pectoralis major":"Musculus pectoralis major","Fächerförmig vom Brustbein und Schlüsselbein zum Oberarm. Er bildet die vordere Achselfalte.":"Віялоподібно йде від груднини та ключиці до плечової кістки. Утворює передню складку пахви.","Er zieht den Arm vor den Körper und dreht ihn nach innen.":"Він тягне руку вперед перед тілом і повертає її всередину.","Ist er verkürzt, zieht er die Schulter nach vorn – das kann die Enge unter dem Schulterdach verstärken.":"Якщо він вкорочений, то тягне плече вперед – це може посилити тісноту під дахом плеча.",Trapezmuskel:o,"Musculus trapezius":"Musculus trapezius","Großer Muskel vom Hinterkopf über den Nacken bis zur Mitte des Rückens, außen am Schulterblatt angewachsen.":"Великий м’яз від потилиці через шию до середини спини, прикріплений до зовнішньої частини лопатки.","Er hebt die Schulter und führt das Schulterblatt.":"Він піднімає плече й спрямовує лопатку.","Der klassische Ort für Nackenverspannungen.":"Класичне місце напруження в ділянці шиї.","Breiter Rückenmuskel":"Найширший м’яз спини","Musculus latissimus dorsi":"Musculus latissimus dorsi","Zieht vom unteren Rücken schräg nach oben zum Oberarm. Er bildet die hintere Achselfalte.":"Іде від нижньої частини спини навскіс угору до плечової кістки. Утворює задню складку пахви.","Er zieht den erhobenen Arm kräftig nach unten und hinten.":"Він сильно тягне підняту руку вниз і назад.","An der Schulter selten die Ursache von Beschwerden.":"Рідко є причиною скарг у плечі.",Gelenkkapsel:b,"Capsula articularis":"Capsula articularis","Umschließt das Schultergelenk wie ein weiter Schlauch.":"Оточує плечовий суглоб, як широка трубка.","Sie dichtet das Gelenk ab und ist bewusst weit, damit der Arm sich in alle Richtungen bewegen kann.":"Вона герметизує суглоб і навмисно вільна, щоб рука могла рухатися в усі боки.","Bei der Schultersteife („Frozen Shoulder“) entzündet sich die Kapsel und schrumpft – der Arm lässt sich kaum noch bewegen.":"За «замороженого плеча» капсула запалюється й зморщується – рука майже не рухається.",Gelenklippe:g,"Labrum glenoidale":"Labrum glenoidale","Ein Ring aus Faserknorpel rund um den Rand der Gelenkpfanne.":"Кільце з волокнистого хряща навколо краю суглобової западини.","Sie vergrößert und vertieft die flache Pfanne wie ein Dichtungsring.":"Вона збільшує й поглиблює пласку западину, як ущільнювальне кільце.","Kann einreißen, wenn die Schulter auskugelt. Das Gelenk bleibt dann oft instabil.":"Може надірватися під час вивиху плеча. Після цього суглоб часто залишається нестабільним.","Band des Schulterdachs":"Зв’язка даху плеча","Ligamentum coracoacromiale":"Ligamentum coracoacromiale","Spannt sich vom Rabenschnabelfortsatz zur Schulterhöhe.":"Натягнута від дзьобоподібного відростка до акроміона.","Zusammen mit dem Knochen bildet es das Dach über dem Oberarmkopf.":"Разом із кісткою утворює дах над голівкою плечової кістки.","Unter diesem Dach wird es eng: Sehne und Schleimbeutel können einklemmen (Engpass-Syndrom).":"Під цим дахом стає тісно: сухожилок і синовіальна сумка можуть затискатися (імпінджмент-синдром).",Schultereckgelenk:k,"Articulatio acromioclavicularis":"Articulatio acromioclavicularis","Kleines Gelenk zwischen dem äußeren Ende des Schlüsselbeins und der Schulterhöhe.":"Невеликий суглоб між зовнішнім кінцем ключиці та акроміоном.","Es lässt das Schulterblatt gegen das Schlüsselbein mitdrehen.":"Він дає змогу лопатці повертатися разом із ключицею.","Verschleißt häufig und schmerzt dann oben auf der Schulter. Bei einem Sturz können die Bänder reißen.":"Часто зношується й тоді болить на верхній частині плеча. Під час падіння зв’язки можуть розірватися.","Haltebänder des Schlüsselbeins":"Зв’язки, що утримують ключицю","Ligamentum coracoclaviculare":"Ligamentum coracoclaviculare","Zwei kurze, kräftige Bänder vom Rabenschnabelfortsatz hinauf zum Schlüsselbein.":"Дві короткі міцні зв’язки від дзьобоподібного відростка вгору до ключиці.","Sie halten das Schlüsselbein unten und tragen das Gewicht des Arms.":"Вони утримують ключицю донизу й несуть вагу руки.","Reißen sie bei einem Sturz auf die Schulter, steht das Schlüsselbein außen sichtbar hoch.":"Якщо вони розриваються під час падіння на плече, зовнішній кінець ключиці помітно випинається вгору.","Schleimbeutel unter dem Schulterdach":"Синовіальна сумка під дахом плеча","Bursa subacromialis":"Bursa subacromialis","Ein flaches Gleitkissen zwischen Schulterdach und Sehnenkappe.":"Пласка ковзна подушка між дахом плеча та сухожилковою манжетою.","Er lässt die Sehnen beim Armheben reibungsarm unter dem Dach gleiten.":"Вона дозволяє сухожилкам ковзати під дахом з малим тертям під час піднімання руки.","Entzündet er sich, schwillt er an und wird eingeklemmt – oft mit starken Schmerzen in der Nacht.":"У разі запалення вона набрякає й затискається – часто з сильним болем уночі.","Was kann wehtun?":"Що може боліти?",Lendenwirbelsäule:"Поперековий відділ хребта","Die Lendenwirbelsäule":"Поперековий відділ хребта","Fünf kräftige Wirbel tragen den Oberkörper. Dazwischen liegen die Bandscheiben, dahinter laufen die Nerven für die Beine.":"П’ять міцних хребців несуть верхню частину тіла. Між ними лежать міжхребцеві диски, позаду проходять нерви для ніг.",Bandscheiben:f,Bänder:"Зв’язки",Nerven:p,Muskeln:z,Lendenwirbel:S,"Vertebrae lumbales":"Vertebrae lumbales","Fünf große Wirbel zwischen Brustkorb und Becken. Vorn der Wirbelkörper, hinten der Bogen mit den kleinen Wirbelgelenken.":"П’ять великих хребців між грудною кліткою та тазом. Спереду тіло хребця, ззаду дуга з дрібними міжхребцевими суглобами.","Die Körper tragen die Last, der Bogen schützt die Nerven, die Gelenke führen die Bewegung.":"Тіла несуть навантаження, дуга захищає нерви, суглоби спрямовують рух.","Verschleiß der kleinen Wirbelgelenke macht tiefsitzenden Kreuzschmerz, vor allem beim Zurückbeugen und nach langem Stehen.":"Зношення дрібних міжхребцевих суглобів спричиняє глибокий біль у попереку, особливо під час нахилу назад і після тривалого стояння.","Kreuzbein und Steißbein":"Крижі та куприк","Os sacrum, Os coccygis":"Os sacrum, Os coccygis","Fünf verschmolzene Wirbel bilden einen Keil zwischen den Beckenschaufeln, unten das Steißbein.":"П’ять зрослих хребців утворюють клин між тазовими кістками, внизу розташований куприк.","Es überträgt die Last der Wirbelsäule auf das Becken.":"Він передає навантаження хребта на таз.","Das Steißbein schmerzt nach einem Sturz aufs Gesäß oft wochenlang.":"Куприк після падіння на сідниці часто болить тижнями.",Beckenschaufeln:w,"Os coxae":"Os coxae","Die beiden großen Beckenknochen rechts und links des Kreuzbeins.":"Дві великі тазові кістки праворуч і ліворуч від крижів.","Sie nehmen die Last auf und geben sie an die Hüftgelenke weiter.":"Вони сприймають навантаження й передають його на кульшові суглоби.","Ein Beckenschiefstand, etwa bei ungleich langen Beinen, belastet die Lendenwirbelsäule einseitig.":"Перекіс таза, наприклад за ніг різної довжини, однобічно навантажує поперековий відділ хребта.","Disci intervertebrales":"Disci intervertebrales","Liegen als Puffer zwischen je zwei Wirbelkörpern. Außen ein fester Faserring, innen ein weicher Kern.":"Лежать як амортизатор між кожною парою тіл хребців. Ззовні міцне фіброзне кільце, всередині м’яке ядро.","Sie federn Stöße ab und machen die Wirbelsäule beweglich.":"Вони пом’якшують поштовхи й роблять хребет рухомим.","Mit den Jahren verlieren sie Wasser und Höhe. Am häufigsten betroffen sind die beiden untersten.":"З роками вони втрачають воду й висоту. Найчастіше страждають два нижніх.",Gallertkern:v,"Nucleus pulposus":"Nucleus pulposus","Der weiche, wasserreiche Kern in der Mitte jeder Bandscheibe.":"М’яке, багате на воду ядро в центрі кожного диска.","Er verteilt den Druck wie ein Wasserkissen gleichmäßig auf den Faserring.":"Воно рівномірно розподіляє тиск на фіброзне кільце, як водяна подушка.","Reißt der Faserring ein, kann der Kern nach hinten austreten und auf eine Nervenwurzel drücken: der Bandscheibenvorfall.":"Якщо фіброзне кільце надривається, ядро може випасти назад і тиснути на корінець нерва: міжхребцева грижа.","Vorderes Längsband":"Передня поздовжня зв’язка","Ligamentum longitudinale anterius":"Ligamentum longitudinale anterius","Ein breites Band vorn auf den Wirbelkörpern, über die ganze Länge der Wirbelsäule.":"Широка зв’язка на передній поверхні тіл хребців по всій довжині хребта.","Es bremst das Überstrecken nach hinten.":"Вона обмежує надмірне розгинання назад.","Macht selten Beschwerden.":"Рідко спричиняє скарги.","Hinteres Längsband":"Задня поздовжня зв’язка","Ligamentum longitudinale posterius":"Ligamentum longitudinale posterius","Läuft im Wirbelkanal auf der Rückseite der Wirbelkörper und Bandscheiben.":"Проходить у хребетному каналі по задній поверхні тіл хребців і дисків.","Es hält die Bandscheiben nach hinten zurück.":"Вона утримує диски від зміщення назад.","In der Mitte ist es kräftig, seitlich schmal – deshalb treten Vorfälle meist seitlich aus, genau dort, wo die Nervenwurzel liegt.":"Посередині вона міцна, з боків вузька – тому грижі найчастіше виходять убік, саме туди, де лежить корінець нерва.","Gelbe Bänder":"Жовті зв’язки","Ligamenta flava":"Ligamenta flava","Elastische Bänder zwischen den Wirbelbögen, an der Rückwand des Wirbelkanals.":"Еластичні зв’язки між дугами хребців, на задній стінці хребетного каналу.","Sie ziehen die Wirbelsäule nach dem Bücken wieder gerade.":"Вони випрямляють хребет після нахилу.","Im Alter verdicken sie und engen zusammen mit den Wirbelgelenken den Kanal ein: die Spinalkanalstenose.":"З віком вони стовщуються й разом із міжхребцевими суглобами звужують канал: стеноз хребетного каналу.","Bänder der Dornfortsätze":"Зв’язки остистих відростків","Ligamenta interspinalia, Ligamentum supraspinale":"Ligamenta interspinalia, Ligamentum supraspinale","Verbinden die nach hinten ragenden Dornfortsätze, die man am Rücken tasten kann.":"З’єднують остисті відростки, спрямовані назад, які можна намацати на спині.","Sie bremsen das Vorbeugen.":"Вони обмежують нахил уперед.","Werden bei ruckartigem Bücken gezerrt – ein Teil des „Hexenschusses“.":"Розтягуються під час різкого нахилу – частина «прострілу» (люмбаго).","Kreuz-Darmbein-Gelenk":"Крижово-клубовий суглоб","Articulatio sacroiliaca":"Articulatio sacroiliaca","Die Fuge zwischen Kreuzbein und Beckenschaufel auf beiden Seiten, mit straffen Bändern überzogen.":"Щілина між крижами та тазовою кісткою з обох боків, вкрита міцними зв’язками.","Es bewegt sich nur wenige Millimeter und federt die Last ab.":"Він рухається лише на кілька міліметрів і амортизує навантаження.","Reizung oder Blockierung schmerzt einseitig tief im Kreuz und zieht ins Gesäß, selten über das Knie hinaus.":"Подразнення або блокада спричиняє біль з одного боку глибоко в попереку, що віддає в сідницю, рідко нижче коліна.","Nervenfasern im Wirbelkanal":"Нервові волокна у хребетному каналі","Cauda equina":"Cauda equina","Das Rückenmark endet schon am ersten Lendenwirbel. Darunter laufen die Nervenwurzeln wie ein Pferdeschweif nach unten.":"Спинний мозок закінчується вже на рівні першого поперекового хребця. Нижче корінці нервів ідуть донизу, як кінський хвіст.","Auf jeder Höhe tritt rechts und links eine Wurzel aus – für Beine, Blase und Darm.":"На кожному рівні праворуч і ліворуч виходить корінець – для ніг, сечового міхура та кишечника.","Wird eine Wurzel gedrückt, strahlt der Schmerz ins Bein aus. Taubheit am Gesäß oder Probleme mit Blase und Darm sind ein Notfall.":"Якщо корінець стиснутий, біль віддає в ногу. Заніміння в ділянці сідниць або проблеми із сечовим міхуром і кишечником – це невідкладна ситуація.",Ischiasnerv:B,"Nervus ischiadicus":"Nervus ischiadicus","Entsteht aus den unteren Nervenwurzeln, verlässt das Becken im Gesäß und läuft hinten am Bein hinab.":"Утворюється з нижніх корінців нервів, виходить із таза в ділянці сідниці й іде вниз по задній стороні ноги.","Er versorgt fast das ganze Bein unterhalb des Knies.":"Він забезпечує майже всю ногу нижче коліна.","„Ischias“ heißt: Schmerz entlang dieses Nervs – die Ursache liegt meist an der Wirbelsäule, nicht im Bein.":"«Ішіас» означає біль уздовж цього нерва – причина здебільшого в хребті, а не в нозі.",Rückenstrecker:"М’яз, що випрямляє хребет","Musculus erector spinae":"Musculus erector spinae","Kräftige Muskelstränge rechts und links der Dornfortsätze, vom Becken bis zum Kopf.":"Потужні м’язові пучки праворуч і ліворуч від остистих відростків, від таза до голови.","Sie richten den Rumpf auf und halten ihn beim Vorbeugen.":"Вони випрямляють тулуб і утримують його під час нахилу вперед.","Die häufigste Ursache von Kreuzschmerz: Verspannung und Überlastung. Bewegung hilft besser als Schonung.":"Найчастіша причина болю в попереку: напруження та перевантаження. Рух допомагає краще, ніж спокій.","Viereckiger Lendenmuskel":"Квадратний м’яз попереку","Musculus quadratus lumborum":"Musculus quadratus lumborum","Liegt tief in der Flanke zwischen unterster Rippe und Beckenkamm.":"Лежить глибоко в боковій ділянці між нижнім ребром і гребенем клубової кістки.","Er neigt den Rumpf zur Seite und stabilisiert beim Tragen.":"Він нахиляє тулуб убік і стабілізує під час перенесення тягарів.","Verspannt er, schmerzt die Flanke einseitig – oft nach einseitigem Heben.":"У разі напруження болить бік з одного боку – часто після піднімання тягаря однією рукою.","Großer Lendenmuskel":"Великий поперековий м’яз","Musculus psoas major":"Musculus psoas major","Entspringt seitlich an den Lendenwirbeln und zieht durch das Becken zum Oberschenkel.":"Починається збоку від поперекових хребців і проходить через таз до стегна.","Der stärkste Hüftbeuger.":"Найсильніший м’яз, що згинає стегно.","Bei langem Sitzen verkürzt er und zieht die Lendenwirbelsäule ins Hohlkreuz.":"За тривалого сидіння він вкорочується й тягне поперековий відділ у прогин (гіперлордоз).",Brustwirbelsäule:"Грудний відділ хребта","Die Brustwirbelsäule":"Грудний відділ хребта","Zwölf Wirbel, jeder mit einem Rippenpaar verbunden. Der Brustkorb macht diesen Abschnitt stabil, aber wenig beweglich.":"Дванадцять хребців, кожен з’єднаний із парою ребер. Грудна клітка робить цей відділ стійким, але малорухомим.","Knochen und Knorpel":"Кістки та хрящі","Bandscheiben und Gelenke":"Міжхребцеві диски та суглоби",Brustwirbel:K,"Vertebrae thoracicae":"Vertebrae thoracicae","Zwölf Wirbel zwischen Hals und Lende. Ihre Dornfortsätze zeigen schräg nach unten wie Dachziegel.":"Дванадцять хребців між шиєю та поперековим відділом. Їхні остисті відростки спрямовані навскіс донизу, як черепиця.","Sie tragen die Rippen und bilden die natürliche Rundung des oberen Rückens.":"Вони несуть ребра й утворюють природний вигин верхньої частини спини.","Bei Osteoporose können die Wirbelkörper einbrechen – oft ohne Sturz. Der Rücken wird runder, man wird kleiner.":"За остеопорозу тіла хребців можуть руйнуватися – часто без падіння. Спина стає більш округлою, зріст зменшується.",Rippen:E,Costae:H,"Zwölf Paare, hinten mit den Wirbeln gelenkig verbunden, vorn über Knorpel mit dem Brustbein.":"Дванадцять пар, ззаду з’єднані з хребцями суглобами, спереду через хрящ із груднини.","Sie schützen Herz und Lunge und heben sich bei jedem Atemzug.":"Вони захищають серце й легені та піднімаються під час кожного вдиху.","Eine Prellung oder ein Bruch schmerzt beim Atmen, Husten und Lachen – oft über Wochen.":"Забій або перелом болить під час дихання, кашлю та сміху – часто тижнями.",Rippenknorpel:D,"Cartilagines costales":"Cartilagines costales","Elastische Knorpelspangen zwischen den Rippen und dem Brustbein.":"Еластичні хрящові дуги між ребрами та груднино.","Sie machen den Brustkorb federnd.":"Вони роблять грудну клітку пружною.","Gereizte Knorpelansätze am Brustbein machen stechenden Brustschmerz, der auf Druck auslösbar ist – harmlos, aber beunruhigend.":"Подразнені місця прикріплення хрящів до груднини спричиняють колючий біль у грудях, який можна викликати натисканням, – нешкідливий, але тривожний.",Brustbein:M,Sternum:A,"Der flache Knochen in der Mitte der Brust.":"Пласка кістка посередині грудей.","Er schließt den Brustkorb nach vorn und trägt die Schlüsselbeine.":"Вона замикає грудну клітку спереду й несе ключиці.","Druckschmerz an seinen Rändern kommt meist von den Rippenknorpeln.":"Болючість на її краях здебільшого походить від реберних хрящів.","Liegt hinten auf den Rippen zwei bis sieben und gleitet dort bei jeder Armbewegung.":"Лежить ззаду на ребрах із другого по сьоме й ковзає по них під час кожного руху руки.","Es ist die bewegliche Basis für den Arm.":"Це рухома опора для руки.","Schmerz „zwischen den Schulterblättern“ kommt meist von den Muskeln, die es halten.":"Біль «між лопатками» здебільшого походить від м’язів, які її утримують.","Zwischen den Wirbelkörpern, hier deutlich flacher als an der Lende.":"Між тілами хребців, тут помітно тонші, ніж у попереку.","Sie federn Stöße ab.":"Вони пом’якшують поштовхи.","Vorfälle sind an der Brustwirbelsäule selten, weil der Brustkorb die Bewegung begrenzt.":"Грижі в грудному відділі хребта рідкісні, бо грудна клітка обмежує рух.","Rippen-Wirbel-Gelenke":"Реберно-хребцеві суглоби","Articulationes costovertebrales":"Articulationes costovertebrales","Jede Rippe ist hinten an zwei Stellen mit der Wirbelsäule verbunden, gehalten von kurzen Bändern.":"Кожне ребро ззаду з’єднане з хребтом у двох місцях і утримується короткими зв’язками.","Um diese Gelenke dreht sich die Rippe beim Atmen.":"Ребро повертається навколо цих суглобів під час дихання.","Eine „Blockierung“ hier macht plötzlichen, stechenden Schmerz neben der Wirbelsäule, der beim Einatmen zunimmt.":"«Блокада» тут спричиняє раптовий колючий біль поруч із хребтом, що посилюється на вдиху.","Ein breites Band vorn auf den Wirbelkörpern.":"Широка зв’язка на передній поверхні тіл хребців.","Es bremst das Überstrecken.":"Вона обмежує надмірне розгинання.","Kann im Alter verknöchern und die Wirbelsäule versteifen.":"З віком може окостеніти й зробити хребет жорстким.",Rückenmark:"Спинний мозок","Medulla spinalis mit Dura mater":"Спинний мозок (Medulla spinalis) з твердою мозковою оболонкою (Dura mater)","Liegt geschützt im Wirbelkanal, umgeben von einer festen Hülle.":"Лежить захищений у хребетному каналі, оточений міцною оболонкою.","Es leitet alle Befehle und Empfindungen zwischen Gehirn und Körper. Auf jeder Höhe zweigt ein Nervenpaar entlang der Rippen ab.":"Він передає всі команди й відчуття між мозком і тілом. На кожному рівні вздовж ребер відходить пара нервів.","Ein gereizter Zwischenrippennerv schmerzt gürtelförmig. Die Gürtelrose folgt genau so einem Nerv.":"Подразнений міжреберний нерв спричиняє поясний біль. Оперізувальний герпес іде саме вздовж такого нерва.","Lange Muskelstränge neben den Dornfortsätzen.":"Довгі м’язові пучки поруч з остистими відростками.","Sie richten den Oberkörper auf.":"Вони випрямляють верхню частину тулуба.","Bei langem Sitzen mit rundem Rücken ermüden sie – der typische Schmerz am Schreibtisch.":"За тривалого сидіння з округлою спиною вони втомлюються – типовий біль за письмовим столом.",Rautenmuskeln:R,"Musculi rhomboidei":"Musculi rhomboidei","Ziehen von den oberen Brustwirbeln schräg zum inneren Rand des Schulterblatts.":"Ідуть від верхніх грудних хребців навскіс до внутрішнього краю лопатки.","Sie ziehen die Schulterblätter zusammen und nach hinten.":"Вони стягують лопатки разом і назад.","Der häufigste Ort für Schmerz zwischen den Schulterblättern.":"Найчастіше місце болю між лопатками.","Bedeckt den oberen Rücken vom Hinterkopf bis zum letzten Brustwirbel.":"Покриває верхню частину спини від потилиці до останнього грудного хребця.","Er führt das Schulterblatt und hebt die Schulter.":"Він спрямовує лопатку й піднімає плече.","Verspannungen ziehen vom Nacken bis zwischen die Schulterblätter.":"Напруження поширюється від шиї до ділянки між лопатками.",Zwischenrippenmuskeln:G,"Musculi intercostales":"Musculi intercostales","Dünne Muskelschichten zwischen den Rippen.":"Тонкі м’язові шари між ребрами.","Sie heben und senken die Rippen beim Atmen.":"Вони піднімають і опускають ребра під час дихання.","Können nach starkem Husten oder ungewohnter Anstrengung gezerrt sein.":"Можуть бути розтягнуті після сильного кашлю або незвичного навантаження.",Halswirbelsäule:"Шийний відділ хребта","Die Halswirbelsäule":"Шийний відділ хребта","Sieben zierliche Wirbel tragen den Kopf und machen ihn in alle Richtungen beweglich. Von hier gehen die Nerven für die Arme ab.":"Сім витончених хребців несуть голову й роблять її рухомою в усі боки. Звідси відходять нерви для рук.","Bandscheiben und Bänder":"Міжхребцеві диски та зв’язки","Nerven und Gefäße":"Нерви та судини","Erster Halswirbel":"Перший шийний хребець",Atlas:O,"Ein Ring ohne Wirbelkörper, direkt unter dem Hinterkopf.":"Кільце без тіла хребця, безпосередньо під потилицею.","Auf ihm ruht der Schädel. Hier entsteht die Nickbewegung („Ja“).":"На ньому спочиває череп. Тут відбувається кивальний рух («так»).","Verspannungen an dieser Stelle machen Kopfschmerz, der vom Nacken nach vorn zieht.":"Напруження в цьому місці спричиняє головний біль, що йде від шиї вперед.","Zweiter Halswirbel":"Другий шийний хребець",Axis:L,"Trägt einen Zapfen, der nach oben in den Ring des ersten Wirbels ragt.":"Несе зубоподібний відросток, що входить угору в кільце першого хребця.","Um diesen Zapfen dreht sich der Kopf („Nein“).":"Навколо цього відростка повертається голова («ні»).","Bei Rheuma kann die Verbindung zum ersten Wirbel locker werden.":"За ревматизму зв’язок із першим хребцем може послабшати.","Dritter bis siebter Halswirbel":"Третій–сьомий шийні хребці","Vertebrae cervicales III–VII":"Vertebrae cervicales III–VII","Fünf kleine Wirbel. Den Dornfortsatz des siebten tastet man unten am Nacken als deutlichen Höcker.":"П’ять невеликих хребців. Остистий відросток сьомого промацується внизу шиї як помітний горбок.","Sie erlauben Beugen, Strecken und Seitneigen des Halses.":"Вони дозволяють нахиляти шию вперед, назад і вбік.","Verschleiß an Bandscheiben und kleinen Gelenken ist ab der Lebensmitte fast normal, am stärksten zwischen fünftem und siebtem Wirbel.":"Зношення дисків і дрібних суглобів із середини життя майже норма, найсильніше між п’ятим і сьомим хребцем.","Zwischen den Wirbelkörpern ab dem zweiten Halswirbel.":"Між тілами хребців, починаючи з другого шийного хребця.","Sie federn den Kopf ab und machen den Hals beweglich.":"Вони пом’якшують навантаження на голову й роблять шию рухомою.","Ein Vorfall drückt auf eine Nervenwurzel: Schmerz, Kribbeln oder Schwäche im Arm bis in einzelne Finger.":"Грижа тисне на корінець нерва: біль, поколювання або слабкість у руці, аж до окремих пальців.",Nackenband:W,"Ligamentum nuchae":"Ligamentum nuchae","Eine Bandplatte in der Mittellinie vom Hinterkopf zu den Dornfortsätzen.":"Зв’язкова пластина по середній лінії від потилиці до остистих відростків.","Es hält den Kopf beim Vorbeugen und ist Ansatz für die Nackenmuskeln.":"Вона утримує голову під час нахилу вперед і слугує місцем прикріплення м’язів шиї.","Wird beim Schleudertrauma gezerrt.":"Розтягується під час «хлистової» травми шиї.","Läuft vom Gehirn durch den Wirbelkanal nach unten, umgeben von einer festen Hülle.":"Іде від мозку вниз хребетним каналом, оточений міцною оболонкою.","Es verbindet das Gehirn mit Armen, Rumpf und Beinen.":"Він з’єднує мозок із руками, тулубом і ногами.","Wird der Kanal durch Verschleiß eng, kann es gedrückt werden: unsichere Hände, unsicherer Gang.":"Якщо канал звужується через зношення, спинний мозок може стискатися: непевність у руках, непевна хода.","Nervenwurzeln für den Arm":"Корінці нервів для руки","Plexus brachialis":"Plexus brachialis","Treten seitlich zwischen den unteren Halswirbeln aus und ziehen zwischen den Treppenmuskeln zur Achsel.":"Виходять збоку між нижніми шийними хребцями й проходять між драбинчастими м’язами до пахви.","Aus ihnen entstehen alle Nerven für Schulter, Arm und Hand.":"З них утворюються всі нерви для плеча, руки та кисті.","Wird eine Wurzel eingeengt, strahlt der Schmerz vom Nacken in den Arm aus – je nach Höhe bis in bestimmte Finger.":"Якщо корінець звужений, біль віддає від шиї в руку – залежно від рівня аж до певних пальців.",Wirbelarterie:N,"Arteria vertebralis":"Arteria vertebralis","Steigt durch Löcher in den Querfortsätzen der Halswirbel zum Kopf auf.":"Піднімається крізь отвори в поперечних відростках шийних хребців до голови.","Sie versorgt Hirnstamm, Kleinhirn und den hinteren Teil des Gehirns.":"Вона постачає кров до стовбура мозку, мозочка та задньої частини мозку.","Ruckartige Manipulationen am Hals können das Gefäß in seltenen Fällen verletzen.":"Різкі маніпуляції на шиї в рідкісних випадках можуть пошкодити судину.",Kopfwender:V,"Musculus sternocleidomastoideus":"Musculus sternocleidomastoideus","Der schräge Strang vom Brustbein und Schlüsselbein zum Knochen hinter dem Ohr.":"Косий тяж від груднини та ключиці до кістки за вухом.","Er dreht den Kopf zur Gegenseite und neigt ihn zur eigenen.":"Він повертає голову в протилежний бік і нахиляє її до свого боку.","Verkrampft er, steht der Kopf schief: der akute Schiefhals.":"Якщо він судомно стискається, голова стоїть набік: гостра кривошия.",Treppenmuskeln:F,"Musculi scaleni":"Musculi scaleni","Drei Muskeln seitlich am Hals, von den Halswirbeln zu den obersten Rippen.":"Три м’язи збоку на шиї, від шийних хребців до найвищих ребер.","Sie neigen den Hals und heben die Rippen beim tiefen Einatmen.":"Вони нахиляють шию й піднімають ребра під час глибокого вдиху.","Zwischen ihnen laufen Armnerven und Schlagader hindurch – bei Verspannung kann der Arm kribbeln.":"Між ними проходять нерви руки й артерія – за напруження рука може поколювати.","Kurze Nackenmuskeln":"Короткі м’язи шиї","Musculi suboccipitales":"Musculi suboccipitales","Vier kleine Muskeln in der Tiefe zwischen Hinterkopf und den beiden obersten Wirbeln.":"Чотири маленькі м’язи глибоко між потилицею та двома найвищими хребцями.","Sie steuern die feinen Kopfbewegungen und melden die Kopfstellung ans Gehirn.":"Вони керують тонкими рухами голови й повідомляють мозку положення голови.","Eine Hauptquelle des Spannungskopfschmerzes – etwa nach langem Blick auf den Bildschirm.":"Одне з головних джерел головного болю напруження – наприклад, після тривалого споглядання екрана.",Nackenstrecker:U,"Musculus splenius, semispinalis, longissimus":"Musculus splenius, semispinalis, longissimus","Mehrere Schichten langer Muskeln hinten am Hals.":"Кілька шарів довгих м’язів на задній стороні шиї.","Sie halten den Kopf aufrecht und strecken ihn nach hinten.":"Вони тримають голову прямо й розгинають її назад.","Je weiter der Kopf nach vorn geneigt ist, desto mehr müssen sie halten – der „Handynacken“.":"Що більше голова нахилена вперед, то більше їм доводиться утримувати – «шия смартфона».","Musculus trapezius, oberer Teil":"Musculus trapezius, верхня частина","Der oberflächliche Muskel vom Hinterkopf zur Schulterhöhe.":"Поверхневий м’яз від потилиці до акроміона.","Er hebt die Schulter und stützt den Kopf.":"Він піднімає плече й підтримує голову.","Der klassische Ort für Nackenverspannungen bei Stress.":"Класичне місце напруження шиї за стресу.",Schulterblattheber:Z,"Musculus levator scapulae":"Musculus levator scapulae","Zieht von den oberen Halswirbeln zur oberen Ecke des Schulterblatts.":"Іде від верхніх шийних хребців до верхнього кута лопатки.","Er hebt das Schulterblatt.":"Він піднімає лопатку.","Ist beim „steifen Hals“ nach Zugluft oder falschem Liegen fast immer beteiligt.":"Майже завжди бере участь у «затяганні шиї» після протягу або незручного положення під час сну.",Schädel:"Череп","Der Schädel":"Череп","Über zwanzig Knochen, fest miteinander verzahnt. Beweglich ist nur der Unterkiefer – in den beiden Kiefergelenken vor den Ohren.":"Понад двадцять кісток, міцно зчеплених між собою. Рухома лише нижня щелепа – у двох скронево-нижньощелепних суглобах перед вухами.",Hirnschädel:"Мозковий відділ черепа",Gesichtsschädel:"Лицевий відділ черепа",Kiefergelenk:I,Kaumuskeln:T,Stirnbein:P,"Os frontale":"Os frontale","Bildet die Stirn und das Dach der Augenhöhlen.":"Утворює чоло та верхню стінку очних ямок.","Es schützt den vorderen Teil des Gehirns.":"Вона захищає передню частину мозку.","Über den Augenbrauen liegen darin die Stirnhöhlen.":"Над бровами в ній розташовані лобові пазухи.",Scheitelbeine:x,"Os parietale":"Os parietale","Zwei gewölbte Platten, die das Schädeldach bilden.":"Дві випуклі пластини, що утворюють склепіння черепа.","Sie decken das Gehirn von oben und von der Seite.":"Вони прикривають мозок зверху й з боків.","Beim Säugling sind die Nähte zwischen den Platten noch offen: die Fontanellen.":"У немовлят шви між пластинами ще відкриті: тім’ячка (джерельця).",Schläfenbeine:"Скроневі кістки","Os temporale":"Os temporale","Seitlich am Kopf rund um das Ohr. Dahinter der tastbare Warzenfortsatz.":"З боків голови навколо вуха. Позаду – соскоподібний відросток, який можна намацати.","Sie enthalten Mittel- und Innenohr und bilden die Pfanne des Kiefergelenks.":"Вони містять середнє й внутрішнє вухо та утворюють западину щелепного суглоба.","An der Schläfe ist der Knochen dünn – ein Schlag dorthin ist besonders gefährlich.":"На скроні кістка тонка – удар туди особливо небезпечний.",Hinterhauptbein:j,"Os occipitale":"Os occipitale","Bildet den Hinterkopf und den hinteren Teil der Schädelbasis mit dem großen Loch für das Rückenmark.":"Утворює потилицю та задню частину основи черепа з великим отвором для спинного мозку.","Es schützt Kleinhirn und Sehrinde und ruht auf dem ersten Halswirbel.":"Вона захищає мозочок і зорову кору й спирається на перший шийний хребець.","Hier setzen die Nackenmuskeln an – der Ausgangspunkt vieler Spannungskopfschmerzen.":"Тут прикріплюються м’язи шиї – вихідна точка багатьох головних болів напруження.",Keilbein:y,"Os sphenoidale":"Os sphenoidale","Liegt wie ein Schmetterling mitten in der Schädelbasis; an der Schläfe kommt es an die Oberfläche.":"Лежить, як метелик, посередині основи черепа; на скроні виходить на поверхню.","Es verbindet Hirn- und Gesichtsschädel. In einer Mulde liegt die Hirnanhangsdrüse.":"Вона з’єднує мозковий і лицевий відділи черепа. У заглибленні лежить гіпофіз.","Von außen nicht zu tasten und selten selbst die Ursache von Beschwerden.":"Ззовні не промацується й сама рідко є причиною скарг.",Jochbeine:C,"Os zygomaticum":"Os zygomaticum","Die Wangenknochen unter den Augen.":"Вилиці під очима.","Sie formen das Gesicht und sind Ursprung des Kaumuskels.":"Вони формують обличчя й є місцем початку жувального м’яза.","Brechen bei einem Schlag oder Sturz auf die Wange.":"Ламаються під час удару або падіння на щоку.",Oberkiefer:J,Maxilla:_,"Trägt die obere Zahnreihe und bildet den Gaumen und den Boden der Augenhöhle.":"Несе верхній ряд зубів і утворює піднебіння та дно очної ямки.","In ihm liegen die Kieferhöhlen, die größten Nasennebenhöhlen.":"У ній розташовані верхньощелепні пазухи – найбільші навколоносові пазухи.","Bei einer Entzündung der Kieferhöhle drückt und klopft es in der Wange, oft schlimmer beim Bücken.":"За запалення верхньощелепної пазухи в щоці відчуваються тиск і пульсація, часто сильніше під час нахилу.","Knochen der Nase":"Кістки носа","Os nasale, Os ethmoidale, Vomer":"Os nasale, Os ethmoidale, Vomer","Das Nasenbein vorn, dahinter Siebbein, Pflugscharbein und Nasenmuscheln.":"Спереду носова кістка, за нею решітчаста кістка, леміш і носові раковини.","Sie formen Nasenrücken, Nasenscheidewand und die Wände der Nasenhöhle.":"Вони формують спинку носа, носову перегородку та стінки порожнини носа.","Das Nasenbein ist der am häufigsten gebrochene Gesichtsknochen. Eine schiefe Scheidewand behindert die Atmung.":"Носова кістка – найчастіше зламувана кістка обличчя. Викривлена перегородка утруднює дихання.",Unterkiefer:q,Mandibula:Q,"Der einzige bewegliche Schädelknochen: ein Bogen mit zwei aufsteigenden Ästen bis vor die Ohren.":"Єдина рухома кістка черепа: дуга з двома висхідними гілками до рівня перед вухами.","Er trägt die untere Zahnreihe und bewegt sich beim Kauen und Sprechen.":"Вона несе нижній ряд зубів і рухається під час жування та мовлення.","Bricht bei einem Schlag aufs Kinn oft an zwei Stellen zugleich.":"За удару в підборіддя часто ламається одразу в двох місцях.",Zähne:"Зуби",Dentes:X,"Stecken mit ihren Wurzeln in Ober- und Unterkiefer.":"Сидять коренями у верхній і нижній щелепі.","Schneiden, reißen und mahlen die Nahrung.":"Ріжуть, рвуть і перетирають їжу.","Zahnwurzeln im Oberkiefer liegen dicht an der Kieferhöhle – eine Entzündung kann von dort übergreifen.":"Корені зубів верхньої щелепи лежать близько до верхньощелепної пазухи – запалення може перейти звідти.",Stirnhöhle:"Лобова пазуха","Sinus frontalis":"Sinus frontalis","Ein luftgefüllter Hohlraum im Stirnbein über den Augenbrauen.":"Заповнена повітрям порожнина в лобовій кістці над бровами.","Wie alle Nebenhöhlen ist sie mit Schleimhaut ausgekleidet und zur Nase hin offen.":"Як і всі навколоносові пазухи, вона вистелена слизовою оболонкою й відкрита в бік носа.","Schwillt die Schleimhaut bei einem Infekt zu, staut sich Sekret: dumpfer Druck über den Augen, schlimmer beim Vorbeugen.":"Якщо слизова оболонка під час інфекції набрякає, скупчується секрет: тупий тиск над очима, сильніше під час нахилу вперед.","Articulatio temporomandibularis":"Articulatio temporomandibularis","Direkt vor dem Ohr: Das Köpfchen des Unterkiefers liegt in einer Grube des Schläfenbeins, umgeben von einer Kapsel.":"Безпосередньо перед вухом: голівка нижньої щелепи лежить у ямці скроневої кістки, оточена капсулою.","Es öffnet den Mund wie ein Scharnier und gleitet dabei nach vorn.":"Він відкриває рот, як шарнір, і при цьому ковзає вперед.","Knacken, Schmerz vor dem Ohr und eingeschränkte Mundöffnung – oft durch Zähneknirschen und Anspannung.":"Клацання, біль перед вухом і обмежене відкривання рота – часто через скреготіння зубами та напруження.",Gelenkscheibe:Y,"Discus articularis":"Discus articularis","Eine kleine Knorpelscheibe zwischen Kieferköpfchen und Gelenkgrube.":"Невеликий хрящовий диск між голівкою щелепи та суглобовою ямкою.","Sie gleitet beim Öffnen mit nach vorn und polstert das Gelenk.":"Під час відкривання він ковзає вперед і пом’якшує суглоб.","Verrutscht sie, knackt es beim Öffnen. Bleibt sie vorn hängen, geht der Mund nicht mehr ganz auf.":"Якщо він зміщується, під час відкривання чути клацання. Якщо застрягає спереду, рот більше не відкривається повністю.",Kaumuskel:$,"Musculus masseter":"Musculus masseter","Vom Jochbogen zum Kieferwinkel. Beim Zusammenbeißen ist er an der Wange zu tasten.":"Від виличної дуги до кута щелепи. Під час стискання зубів його можна намацати на щоці.","Er schließt den Kiefer mit großer Kraft.":"Він із великою силою закриває щелепу.","Bei nächtlichem Knirschen ist er morgens verspannt und druckschmerzhaft; der Schmerz kann in Zähne und Ohr ausstrahlen.":"За нічного скреготіння зубами вранці він напружений і болючий під час натискання; біль може віддавати в зуби та вухо.",Schläfenmuskel:"Скроневий м’яз","Musculus temporalis":"Musculus temporalis","Ein Fächer an der Schläfe, dessen Sehne unter dem Jochbogen zum Unterkiefer zieht.":"Віяло на скроні, сухожилок якого проходить під виличною дугою до нижньої щелепи.","Er schließt den Kiefer und zieht ihn zurück.":"Він закриває щелепу й тягне її назад.","Verspannt er, entsteht Kopfschmerz an den Schläfen.":"У разі напруження виникає головний біль у скронях.",Flügelmuskeln:"Крилоподібні м’язи","Musculi pterygoidei":"Musculi pterygoidei","Liegen in der Tiefe an der Innenseite des Unterkieferasts.":"Лежать глибоко на внутрішньому боці гілки нижньої щелепи.","Sie schieben den Kiefer nach vorn und zur Seite – die Mahlbewegung.":"Вони рухають щелепу вперед і вбік – жувальний рух.","Einer setzt direkt an der Gelenkscheibe an; bei Verspannung kann er sie verziehen.":"Один із них прикріплюється безпосередньо до суглобового диска; за напруження може змістити його.",Ellenbogen:ee,"Der Ellenbogen":"Лікоть","Drei Knochen treffen sich hier: Der Arm lässt sich beugen und strecken, und der Unterarm dreht sich um die eigene Achse.":"Тут зустрічаються три кістки: руку можна згинати й розгинати, а передпліччя обертається навколо власної осі.","Muskeln und Sehnen":"М’язи та сухожилки","Sein unteres Ende bildet eine Rolle und ein Köpfchen, dazu innen und außen je einen tastbaren Knochenvorsprung.":"Його нижній кінець утворює блок і голівку, а також із внутрішнього й зовнішнього боку по кістковому виступу, який можна намацати.","An den beiden Vorsprüngen entspringen die Muskeln für Handgelenk und Finger.":"Від цих двох виступів починаються м’язи для зап’ястка й пальців.","Die Vorsprünge sind der Ort von Tennis- und Golferellenbogen.":"Ці виступи – місце виникнення «тенісного» і «гольфістського» ліктя.",Elle:ne,Ulna:ie,"Liegt auf der Kleinfingerseite. Ihr oberes Ende, der Ellenhaken, ist die Spitze des Ellenbogens.":"Лежить з боку мізинця. Її верхній кінець, ліктьовий відросток, – це кінчик ліктя.","Sie umgreift die Rolle des Oberarmknochens wie eine Zange – das ist das Scharnier.":"Вона охоплює блок плечової кістки, як обценьки, – це і є шарнір.","Ein Sturz auf den Ellenbogen kann den Ellenhaken brechen. Der Schleimbeutel darüber schwillt leicht an.":"Падіння на лікоть може зламати ліктьовий відросток. Синовіальна сумка над ним легко набрякає.",Speiche:re,Radius:se,"Liegt auf der Daumenseite. Ihr rundes Köpfchen sitzt direkt unter dem Oberarmknochen.":"Лежить з боку великого пальця. Її кругла голівка розташована безпосередньо під плечовою кісткою.","Das Köpfchen dreht sich bei jeder Umwendbewegung der Hand.":"Голівка повертається під час кожного обертального руху кисті.","Das Speichenköpfchen bricht bei einem Sturz auf die ausgestreckte Hand.":"Голівка променевої кістки ламається під час падіння на витягнуту руку.",Bizeps:te,"Musculus biceps brachii":"Musculus biceps brachii","Vorn am Oberarm. Seine Sehne zieht in die Ellenbeuge und setzt an der Speiche an.":"На передній стороні плеча. Його сухожилок іде в ліктьовий згин і прикріплюється до променевої кістки.","Er beugt den Ellenbogen und dreht die Handfläche nach oben.":"Він згинає лікоть і повертає долоню вгору.","Die untere Sehne kann bei ruckartigem Heben reißen – mit plötzlichem Schmerz in der Ellenbeuge.":"Нижній сухожилок може розірватися за різкого піднімання тягаря – з раптовим болем у ліктьовому згині.",Armbeuger:ae,"Musculus brachialis":"Musculus brachialis","Liegt unter dem Bizeps direkt auf dem Knochen und setzt an der Elle an.":"Лежить під біцепсом безпосередньо на кістці й прикріплюється до ліктьової кістки.","Der eigentliche Kraftbeuger des Ellenbogens.":"Справжній силовий згинач ліктя.","Auf der Rückseite des Oberarms. Seine Sehne setzt am Ellenhaken an.":"На задній стороні плеча. Його сухожилок прикріплюється до ліктьового відростка.","Die Sehne kann am Ansatz gereizt sein, etwa nach viel Stützen oder Drücken.":"Сухожилок може подразнюватися в місці прикріплення, наприклад, після частого впору або віджимань.",Oberarmspeichenmuskel:le,"Musculus brachioradialis":"Musculus brachioradialis","Zieht außen vom Oberarm über den Ellenbogen bis zum Handgelenk.":"Іде зовні від плеча через лікоть до зап’ястка.","Er beugt den Ellenbogen, vor allem in Mittelstellung – wie beim Tragen einer Tasche.":"Він згинає лікоть, особливо в середньому положенні – як під час перенесення сумки.","Kann bei Überlastung verspannen.":"За перевантаження може напружуватися.","Streckmuskeln der Hand":"Розгиначі кисті","Extensoren des Unterarms":"Розгиначі передпліччя","Entspringen gemeinsam am äußeren Knochenvorsprung des Oberarms und laufen zum Handrücken.":"Починаються разом від зовнішнього кісткового виступу плечової кістки й ідуть до тильної сторони кисті.","Sie heben das Handgelenk und strecken die Finger.":"Вони піднімають зап’ясток і розгинають пальці.","Am gemeinsamen Sehnenansatz entsteht der Tennisellenbogen: Schmerz außen, etwa beim Greifen und Heben.":"У місці спільного прикріплення сухожилків виникає «тенісний лікоть»: біль зовні, наприклад, під час захоплення й піднімання.","Beugemuskeln der Hand":"Згиначі кисті","Flexoren des Unterarms":"Згиначі передпліччя","Entspringen gemeinsam am inneren Knochenvorsprung des Oberarms und laufen zur Handfläche.":"Починаються разом від внутрішнього кісткового виступу плечової кістки й ідуть до долоні.","Sie beugen Handgelenk und Finger und drehen die Handfläche nach unten.":"Вони згинають зап’ясток і пальці та повертають долоню вниз.","Am gemeinsamen Sehnenansatz entsteht der Golferellenbogen: Schmerz innen am Ellenbogen.":"У місці спільного прикріплення сухожилків виникає «лікоть гольфіста»: біль на внутрішньому боці ліктя.",Auswärtsdreher:"Супінатор","Musculus supinator":"Musculus supinator","Wickelt sich in der Tiefe außen um das obere Ende der Speiche.":"Обвиває глибоко ззовні верхній кінець променевої кістки.","Er dreht die Handfläche nach oben, zum Beispiel beim Schrauben.":"Він повертає долоню вгору, наприклад, під час закручування.","Kann einen Nervenast einengen, der durch ihn hindurchzieht.":"Може стискати гілку нерва, що проходить крізь нього.","Umschließt alle drei Teilgelenke des Ellenbogens gemeinsam.":"Охоплює всі три складові частини ліктьового суглоба разом.","Sie dichtet das Gelenk ab und hält die Gelenkflüssigkeit.":"Вона герметизує суглоб і утримує суглобову рідину.","Nach Verletzungen oder langer Ruhigstellung schrumpft sie leicht – der Arm lässt sich dann nicht mehr ganz strecken.":"Після травм або тривалої іммобілізації вона трохи зморщується – рука тоді вже не розгинається повністю.",Ringband:ue,"Ligamentum anulare radii":"Ligamentum anulare radii","Legt sich wie eine Schlaufe um das Köpfchen der Speiche.":"Охоплює голівку променевої кістки, як петля.","Es hält die Speiche an der Elle und lässt sie sich trotzdem drehen.":"Вона утримує променеву кістку біля ліктьової й усе ж дозволяє їй обертатися.","Bei Kleinkindern kann das Köpfchen herausrutschen, wenn am Arm gezogen wird.":"У маленьких дітей голівка може вислизнути, якщо потягнути за руку.",Innenband:de,"Ligamentum collaterale ulnare":"Ligamentum collaterale ulnare","Zieht innen vom Oberarmknochen zur Elle.":"Іде зсередини від плечової кістки до ліктьової кістки.","Es verhindert, dass der Ellenbogen nach innen aufklappt.":"Вона не дає ліктю розкритися всередину.","Wird bei Wurfsportarten überlastet oder reißt beim Auskugeln.":"Перевантажується в метальних видах спорту або розривається під час вивиху.",Außenband:"Зовнішня бокова зв’язка","Ligamentum collaterale radiale":"Ligamentum collaterale radiale","Zieht außen vom Oberarmknochen zum Ringband.":"Іде зовні від плечової кістки до кільцевої зв’язки.","Es sichert den Ellenbogen nach außen.":"Вона страхує лікоть ззовні.","Kann bei einem Sturz auf den gestreckten Arm reißen.":"Може розірватися під час падіння на випрямлену руку.",Ellennerv:ce,"Nervus ulnaris":"Nervus ulnaris","Läuft innen hinter dem Knochenvorsprung in einer Rinne, direkt unter der Haut.":"Проходить зсередини позаду кісткового виступу в жолобку, безпосередньо під шкірою.","Er versorgt Ring- und kleinen Finger und viele kleine Handmuskeln.":"Він забезпечує безіменний палець і мізинець та багато дрібних м’язів кисті.","Der „Musikantenknochen“: Ein Stoß elektrisiert. Dauerdruck, etwa durch Aufstützen, lässt die Finger kribbeln.":"«Музична кісточка»: удар відчувається як електричний струм. Постійний тиск, наприклад, під час обпирання на лікоть, спричиняє поколювання в пальцях.",Hand:he,"Die Hand":"Кисть","27 Knochen, bewegt von Muskeln im Unterarm: Ihre langen Sehnen laufen über das Handgelenk bis in die Fingerspitzen.":"27 кісток, що приводяться в рух м’язами передпліччя: їхні довгі сухожилки йдуть через зап’ясток до кінчиків пальців.","Bänder und Gelenk":"Зв’язки та суглоб",Sehnenscheiden:me,"Der Unterarmknochen auf der Daumenseite. Am Handgelenk ist er breit und trägt die Handwurzel.":"Кістка передпліччя з боку великого пальця. У ділянці зап’ястка вона широка й несе кістки зап’ястка.","Er bildet den größten Teil des Handgelenks.":"Вона утворює більшу частину променезап’ясткового суглоба.","Der häufigste Knochenbruch überhaupt: Sturz auf die ausgestreckte Hand.":"Найчастіший перелом кістки взагалі: падіння на витягнуту руку.","Der Unterarmknochen auf der Kleinfingerseite. Ihr Köpfchen ist außen am Handgelenk zu tasten.":"Кістка передпліччя з боку мізинця. Її голівку можна намацати ззовні на зап’ястку.","Um sie herum dreht sich die Speiche beim Umwenden der Hand.":"Навколо неї повертається променева кістка, коли кисть розвертають.","Schmerzen auf der Kleinfingerseite kommen oft von der Knorpelscheibe an ihrem Ende.":"Біль з боку мізинця часто походить від хрящового диска на її кінці.",Kahnbein:oe,"Os scaphoideum":"Os scaphoideum","Handwurzelknochen auf der Daumenseite, direkt an der Speiche.":"Кістка зап’ястка з боку великого пальця, безпосередньо біля променевої кістки.","Es verbindet die beiden Reihen der Handwurzel.":"Вона з’єднує два ряди кісток зап’ястка.","Bricht bei einem Sturz auf die Hand, wird leicht übersehen und heilt langsam.":"Ламається під час падіння на кисть, легко залишається непоміченою й заживає повільно.",Daumensattelgelenk:be,"Os trapezium, Articulatio carpometacarpalis I":"Os trapezium, Articulatio carpometacarpalis I","Das große Vieleckbein an der Daumenwurzel bildet mit dem ersten Mittelhandknochen einen Sattel.":"Велика трапецієподібна кістка в основі великого пальця утворює з першою п’ястковою кісткою сідло.","Dieses Gelenk macht den Daumen so beweglich, dass er jedem Finger gegenübertreten kann.":"Цей суглоб робить великий палець настільки рухомим, що він може протиставлятися кожному пальцю.","Verschleiß an dieser Stelle ist häufig: Schmerz an der Daumenwurzel beim Drehen und festen Greifen.":"Зношення в цьому місці часте: біль в основі великого пальця під час обертання та міцного захоплення.",Handwurzelknochen:ge,"Ossa carpi":"Ossa carpi","Kleine Knochen in zwei Reihen zwischen Unterarm und Mittelhand.":"Дрібні кістки у два ряди між передпліччям і п’ясткою.","Gemeinsam machen sie das Handgelenk in viele Richtungen beweglich.":"Разом вони роблять зап’ясток рухомим у багатьох напрямках.","Bänder zwischen den Knochen können bei Stürzen reißen.":"Зв’язки між кістками можуть розірватися під час падінь.",Mittelhandknochen:ke,"Ossa metacarpi":"Ossa metacarpi","Fünf Röhrenknochen, die den Handteller bilden.":"П’ять трубчастих кісток, що утворюють долоню.","Sie tragen die Finger und geben der Hand ihre Wölbung.":"Вони несуть пальці й надають кисті її склепіння.","Der fünfte bricht typischerweise bei einem Faustschlag.":"П’ята типово ламається під час удару кулаком.",Fingerknochen:fe,Phalanges:pe,"Je drei Glieder pro Finger, zwei am Daumen.":"По три фаланги на кожному пальці, дві на великому.","Zwischen ihnen liegen Scharniergelenke zum Beugen und Strecken.":"Між ними розташовані блокоподібні суглоби для згинання та розгинання.","An den End- und Mittelgelenken zeigt sich Arthrose als Knoten.":"У кінцевих і середніх суглобах артроз проявляється вузликами.","Beugesehnen der Finger":"Сухожилки згиначів пальців","Musculi flexores digitorum":"Musculi flexores digitorum","Die Muskeln liegen im Unterarm. Ihre Sehnen ziehen durch den Karpaltunnel in die Handfläche und zu den Fingern.":"М’язи розташовані в передпліччі. Їхні сухожилки проходять через зап’ястковий канал у долоню та до пальців.","Sie schließen die Hand zur Faust.":"Вони стискають кисть у кулак.","Verdickt sich eine Sehne, bleibt sie an ihrem Ringband hängen: der schnellende Finger.":"Якщо сухожилок потовщується, він застрягає в кільцевій зв’язці: «клацаючий палець».","Strecksehnen der Finger":"Сухожилки розгиначів пальців","Musculus extensor digitorum":"Musculus extensor digitorum","Laufen flach über den Handrücken – beim Spreizen der Finger sieht man sie unter der Haut.":"Ідуть плоско по тильній стороні кисті – під час розчепірювання пальців їх видно під шкірою.","Sie öffnen die Hand und strecken die Finger.":"Вони розкривають кисть і розгинають пальці.","Am Endglied kann die Sehne abreißen, dann hängt die Fingerkuppe herab.":"На кінцевій фаланзі сухожилок може відірватися, тоді кінчик пальця звисає.",Daumensehnen:ze,"Musculus abductor pollicis longus, extensor pollicis brevis":"Musculus abductor pollicis longus, extensor pollicis brevis","Zwei Sehnen, die auf der Daumenseite über das Handgelenk zum Daumen laufen.":"Два сухожилки, що йдуть з боку великого пальця через зап’ясток до великого пальця.","Sie spreizen und strecken den Daumen.":"Вони відводять і розгинають великий палець.","Sie teilen sich ein enges Sehnenfach. Entzündet es sich, schmerzt jede Daumenbewegung.":"Вони ділять вузьку сухожилкову піхву. У разі запалення болить кожен рух великого пальця.",Daumenballen:Se,Thenar:we,"Das Muskelpolster an der Daumenwurzel.":"М’язова подушка в основі великого пальця.","Die kurzen Muskeln führen den Daumen zu den anderen Fingern.":"Короткі м’язи підводять великий палець до інших пальців.","Beim Karpaltunnelsyndrom wird der Ballen schwächer und flacher.":"За синдрому зап’ясткового каналу підвищення слабшає й стає площим.",Kleinfingerballen:ve,Hypothenar:Be,"Das Muskelpolster an der Handkante.":"М’язова подушка на краю кисті.","Es bewegt den kleinen Finger und polstert die Hand beim Aufstützen.":"Вона рухає мізинець і пом’якшує опору на кисть.","Wird schwächer, wenn der Ellennerv geschädigt ist.":"Слабшає, якщо ліктьовий нерв пошкоджений.",Karpalband:Ke,"Retinaculum flexorum":"Retinaculum flexorum","Ein straffes Band quer über der Handwurzel. Darunter liegt der Karpaltunnel.":"Міцна зв’язка впоперек зап’ястка. Під нею лежить зап’ястковий канал.","Es hält die Beugesehnen am Handgelenk in der Spur.":"Вона утримує сухожилки згиначів на зап’ястку на своєму шляху.","Wird es im Tunnel zu eng, drückt es auf den Mittelnerv. Bei der Operation wird dieses Band gespalten.":"Якщо в каналі стає занадто тісно, вона тисне на серединний нерв. Під час операції цю зв’язку розсікають.","Sehnenplatte der Hohlhand":"Долонний апоневроз","Aponeurosis palmaris":"Aponeurosis palmaris","Eine feste Bindegewebsplatte direkt unter der Haut der Handfläche.":"Щільна пластина сполучної тканини безпосередньо під шкірою долоні.","Sie schützt Sehnen und Nerven und gibt der Haut beim Greifen Halt.":"Вона захищає сухожилки й нерви та забезпечує шкірі зчеплення під час захоплення.","Bildet sie Knoten und Stränge, ziehen sich Finger langsam in die Beugung.":"Якщо в ній утворюються вузли й тяжі, пальці поступово стягуються в зігнуте положення.","Kapsel des Handgelenks":"Капсула променезап’ясткового суглоба","Capsula articularis radiocarpalis":"Capsula articularis radiocarpalis","Umschließt das Gelenk zwischen Speiche und Handwurzel.":"Оточує суглоб між променевою кісткою та кістками зап’ястка.","Sie dichtet das Handgelenk ab.":"Вона герметизує променезап’ястковий суглоб.","Aus ihr stülpt sich häufig ein prall-elastischer Knoten aus, das Überbein.":"З неї часто випинається щільно-еластичний вузол – гігрома (ганглій).","Knorpelscheibe an der Elle":"Хрящовий диск біля ліктьової кістки","Discus ulnocarpalis":"Discus ulnocarpalis","Eine kleine Scheibe zwischen dem Ellenköpfchen und der Handwurzel.":"Невеликий диск між голівкою ліктьової кістки та зап’ястком.","Sie polstert die Kleinfingerseite des Handgelenks.":"Він пом’якшує бік зап’ястка з боку мізинця.","Kann einreißen oder verschleißen: Schmerz außen am Handgelenk beim Drehen und Abstützen.":"Може надірватися або зноситися: біль зовні на зап’ястку під час обертання та опори.","Sehnenscheiden der Beuger":"Сухожилкові піхви згиначів","Vaginae synoviales digitorum manus":"Vaginae synoviales digitorum manus","Gleitröhren, in denen die Beugesehnen durch Handfläche und Finger laufen.":"Ковзні трубки, у яких сухожилки згиначів проходять через долоню та пальці.","Sie lassen die Sehnen reibungsarm gleiten.":"Вони дозволяють сухожилкам ковзати з малим тертям.","Bei Überlastung entzünden sie sich: Schmerz und Reiben bei jeder Bewegung.":"За перевантаження вони запалюються: біль і тертя під час кожного руху.","Sehnenfach am Daumen":"Сухожилкова піхва біля великого пальця","Erstes Strecksehnenfach":"Перший канал сухожилків-розгиначів","Liegt auf der Daumenseite des Handgelenks über dem Ende der Speiche.":"Лежить на боці великого пальця зап’ястка над кінцем променевої кістки.","Es führt die beiden Daumensehnen um das Handgelenk.":"Воно спрямовує два сухожилки великого пальця навколо зап’ястка.","Wird es zu eng, schmerzt es hier beim Greifen und Wringen – typisch bei jungen Eltern und viel Handarbeit.":"Якщо в ньому стає занадто тісно, тут болить під час захоплення та вижимання – типово в молодих батьків і за великого обсягу ручної роботи.",Mittelnerv:Ee,"Nervus medianus":"Nervus medianus","Zieht mit den Beugesehnen durch den Karpaltunnel in die Hand.":"Проходить разом із сухожилками згиначів через зап’ястковий канал у кисть.","Er gibt Gefühl an Daumen, Zeige- und Mittelfinger und steuert den Daumenballen.":"Він забезпечує чутливість великого, вказівного та середнього пальців і керує підвищенням великого пальця.","Wird er im Tunnel gedrückt, schlafen die Finger ein – vor allem nachts.":"Якщо він стиснутий у каналі, пальці німіють – особливо вночі.","Läuft auf der Kleinfingerseite neben dem Erbsenbein in die Hand.":"Проходить з боку мізинця поруч із горохоподібною кісткою в кисть.","Er gibt Gefühl am kleinen Finger und steuert die meisten kleinen Handmuskeln.":"Він забезпечує чутливість мізинця й керує більшістю дрібних м’язів кисті.","Dauerdruck auf die Handkante, etwa am Fahrradlenker, lässt den kleinen Finger taub werden.":"Постійний тиск на край кисті, наприклад, на кермі велосипеда, спричиняє заніміння мізинця."};export{ae as Armbeuger,O as Atlas,L as Axis,f as Bandscheiben,w as Beckenschaufeln,te as Bizeps,M as Brustbein,K as Brustwirbel,u as Clavicula,H as Costae,Se as Daumenballen,be as Daumensattelgelenk,ze as Daumensehnen,h as Deltamuskel,X as Dentes,ne as Elle,ee as Ellenbogen,ce as Ellennerv,fe as Fingerknochen,v as Gallertkern,b as Gelenkkapsel,g as Gelenklippe,Y as Gelenkscheibe,he as Hand,ge as Handwurzelknochen,n as Haupt,j as Hinterhauptbein,c as Humerus,Be as Hypothenar,de as Innenband,B as Ischiasnerv,e as JPEG,C as Jochbeine,oe as Kahnbein,Ke as Karpalband,$ as Kaumuskel,T as Kaumuskeln,y as Keilbein,I as Kiefergelenk,ve as Kleinfingerballen,V as Kopfwender,S as Lendenwirbel,Q as Mandibula,_ as Maxilla,ke as Mittelhandknochen,Ee as Mittelnerv,z as Muskeln,W as Nackenband,U as Nackenstrecker,p as Nerven,d as Oberarmknochen,le as Oberarmspeichenmuskel,J as Oberkiefer,i as Organe,pe as Phalanges,se as Radius,R as Rautenmuskeln,ue as Ringband,E as Rippen,D as Rippenknorpel,s as Rotatorenmanschette,l as Scapula,x as Scheitelbeine,t as Schleimbeutel,r as Schulter,a as Schulterblatt,Z as Schulterblattheber,k as Schultereckgelenk,me as Sehnenscheiden,re as Speiche,A as Sternum,P as Stirnbein,we as Thenar,o as Trapezmuskel,F as Treppenmuskeln,m as Trizeps,ie as Ulna,q as Unterkiefer,N as Wirbelarterie,G as Zwischenrippenmuskeln,He as default};
